# Modular Real-Time Chat Server in C#

Below is a comprehensive implementation of a modular real-time chat server in C# with the three requested components. This design follows SOLID principles and separates concerns while maintaining loose coupling between components.

## Project Structure

```
ChatServer/
├── ConnectionManager/          # TCP Connection Manager
├── RoomManagement/             # Room Management Subsystem
├── PersistenceEngine/          # Message Persistence Engine
├── Shared/                     # Shared interfaces and models
└── ChatServerHost/             # Main application host
```

## 1. Shared Interfaces and Models

```csharp
// Shared/Models/Message.cs
public class ChatMessage
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public string SenderId { get; set; }
    public string RoomId { get; set; }
    public string Content { get; set; }
    public DateTime Timestamp { get; set; } = DateTime.UtcNow;
    public string? ImageUrl { get; set; }
    public MessageType Type { get; set; }
}

public enum MessageType
{
    Text,
    Image,
    System
}

// Shared/Interfaces/IConnection.cs
public interface IConnection : IDisposable
{
    string ConnectionId { get; }
    string UserId { get; set; }
    string? RoomId { get; set; }
    Task SendMessageAsync(ChatMessage message);
    Task SendSystemMessageAsync(string message);
    Task<bool> SendHeartbeatAsync();
    Task<bool> ReceiveHeartbeatAsync();
    Task CloseAsync();
}

// Shared/Interfaces/IRoomManager.cs
public interface IRoomManager
{
    Task<string> CreateRoomAsync(string creatorId, string roomName, RoomPermissions permissions);
    Task<bool> JoinRoomAsync(string connectionId, string roomId);
    Task<bool> LeaveRoomAsync(string connectionId);
    Task<bool> SendMessageToRoomAsync(string roomId, ChatMessage message);
    Task<bool> BroadcastSystemMessageAsync(string roomId, string message);
    Task<IEnumerable<string>> GetRoomMembersAsync(string roomId);
    Task<RoomPermissions> GetRoomPermissionsAsync(string roomId);
    Task<bool> UpdateRoomPermissionsAsync(string roomId, RoomPermissions permissions);
}

public class RoomPermissions
{
    public bool CanCreate { get; set; } = true;
    public bool CanJoin { get; set; } = true;
    public bool CanSendMessages { get; set; } = true;
    public bool CanManagePermissions { get; set; } = false;
}

// Shared/Interfaces/IMessagesRepository.cs
public interface IMessagesRepository
{
    Task AddMessageAsync(ChatMessage message);
    Task<IEnumerable<ChatMessage>> GetMessagesAsync(string roomId, int limit = 100);
    Task<IEnumerable<ChatMessage>> GetMessagesSinceAsync(string roomId, DateTime since);
}

// Shared/Interfaces/IMessageProcessor.cs
public interface IMessageProcessor
{
    Task ProcessMessageAsync(ChatMessage message);
}
