## 2. TCP Connection Manager

```csharp
// ConnectionManager/TcpConnection.cs
public class TcpConnection : IConnection, IDisposable
{
    private readonly TcpClient _tcpClient;
    private readonly NetworkStream _networkStream;
    private readonly BinaryFormatter _formatter = new BinaryFormatter();
    private readonly ILogger<TcpConnection> _logger;
    private readonly IMessageProcessor _messageProcessor;
    private readonly IRoomManager _roomManager;
    private readonly TimeSpan _heartbeatInterval = TimeSpan.FromSeconds(30);
    private readonly TimeSpan _heartbeatTimeout = TimeSpan.FromSeconds(45);
    private readonly CancellationTokenSource _cts = new CancellationTokenSource();
    private DateTime _lastHeartbeat;
    private bool _disposed;

    public string ConnectionId { get; }
    public string UserId { get; set; }
    public string? RoomId { get; set; }

    public TcpConnection(TcpClient tcpClient, string connectionId,
                        ILogger<TcpConnection> logger,
                        IMessageProcessor messageProcessor,
                        IRoomManager roomManager)
    {
        _tcpClient = tcpClient ?? throw new ArgumentNullException(nameof(tcpClient));
        _networkStream = tcpClient.GetStream();
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _messageProcessor = messageProcessor ?? throw new ArgumentNullException(nameof(messageProcessor));
        _roomManager = roomManager ?? throw new ArgumentNullException(nameof(roomManager));
        ConnectionId = connectionId;

        _lastHeartbeat = DateTime.UtcNow;
        StartHeartbeatMonitor();
    }

    public async Task SendMessageAsync(ChatMessage message)
    {
        try
        {
            var buffer = _formatter.Serialize(new { Type = "message", Data = message });
            await _networkStream.WriteAsync(buffer, 0, buffer.Length);
            _logger.LogDebug("Sent message to {ConnectionId}", ConnectionId);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error sending message to {ConnectionId}", ConnectionId);
            throw;
        }
    }

    public async Task SendSystemMessageAsync(string message)
    {
        try
        {
            var buffer = _formatter.Serialize(new { Type = "system", Data = message });
            await _networkStream.WriteAsync(buffer, 0, buffer.Length);
            _logger.LogDebug("Sent system message to {ConnectionId}", ConnectionId);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error sending system message to {ConnectionId}", ConnectionId);
            throw;
        }
    }

    public async Task<bool> SendHeartbeatAsync()
    {
        try
        {
            _lastHeartbeat = DateTime.UtcNow;
            var buffer = _formatter.Serialize(new { Type = "heartbeat" });
            await _networkStream.WriteAsync(buffer, 0, buffer.Length);
            return true;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error sending heartbeat from {ConnectionId}", ConnectionId);
            return false;
        }
    }

    public async Task<bool> ReceiveHeartbeatAsync()
    {
        try
        {
            var buffer = new byte[1024];
            var bytesRead = await _networkStream.ReadAsync(buffer, 0, buffer.Length);
            if (bytesRead == 0) return false;

            var data = _formatter.Deserialize(new MemoryStream(buffer, 0, bytesRead));
            if (data is { Type: "heartbeat" })
            {
                _lastHeartbeat = DateTime.UtcNow;
                return true;
            }
            return false;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error receiving heartbeat from {ConnectionId}", ConnectionId);
            return false;
        }
    }

    public async Task CloseAsync()
    {
        if (_disposed) return;

        try
        {
            if (RoomId != null)
            {
                await _roomManager.LeaveRoomAsync(ConnectionId);
            }

            await _networkStream.CloseAsync();
            await _tcpClient.CloseAsync();
            _cts.Cancel();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error closing connection {ConnectionId}", ConnectionId);
        }
        finally
        {
            _disposed = true;
        }
    }

    private async Task HeartbeatMonitor()
    {
        while (!_cts.IsCancellationRequested)
        {
            try
            {
                if ((DateTime.UtcNow - _lastHeartbeat) > _heartbeatTimeout)
                {
                    _logger.LogWarning("Heartbeat timeout for {ConnectionId}", ConnectionId);
                    await CloseAsync();
                    return;
                }

                await Task.Delay(_heartbeatInterval, _cts.Token);
            }
            catch (OperationCanceledException)
            {
                // Expected on cancellation
                break;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error in heartbeat monitor for {ConnectionId}", ConnectionId);
                break;
            }
        }
    }

    private void StartHeartbeatMonitor()
    {
        Task.Run(HeartbeatMonitor, _cts.Token);
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (!_disposed)
        {
            if (disposing)
            {
                _cts.Cancel();
                _cts.Dispose();
                _networkStream?.Dispose();
                _tcpClient?.Dispose();
            }
            _disposed = true;
        }
    }

    ~TcpConnection()
    {
        Dispose(false);
    }
}

// ConnectionManager/TcpConnectionManager.cs
public class TcpConnectionManager : IDisposable
{
    private readonly TcpListener _listener;
    private readonly ILogger<TcpConnectionManager> _logger;
    private readonly IConnectionFactory _connectionFactory;
    private readonly ConcurrentDictionary<string, IConnection> _connections = new();
    private readonly CancellationTokenSource _cts = new();
    private bool _disposed;

    public event Action<IConnection>? ConnectionAdded;
    public event Action<IConnection>? ConnectionRemoved;

    public TcpConnectionManager(int port, ILogger<TcpConnectionManager> logger, IConnectionFactory connectionFactory)
    {
        _listener = new TcpListener(IPAddress.Any, port);
        _logger = logger;
        _connectionFactory = connectionFactory ?? throw new ArgumentNullException(nameof(connectionFactory));
    }

    public async Task StartAsync()
    {
        _listener.Start();
        _logger.LogInformation("TCP Connection Manager started on port {Port}", _listener.LocalPort);

        try
        {
            while (!_cts.IsCancellationRequested)
            {
                try
                {
                    var tcpClient = await _listener.AcceptTcpClientAsync();
                    var connection = _connectionFactory.CreateConnection(tcpClient);
                    _connections.TryAdd(connection.ConnectionId, connection);

                    ConnectionAdded?.Invoke(connection);
                    _logger.LogInformation("New connection established: {ConnectionId}", connection.ConnectionId);

                    // Start processing messages in background
                    Task.Run(async () =>
                    {
                        try
                        {
                            await ProcessConnectionAsync(connection);
                        }
                        catch (Exception ex)
                        {
                            _logger.LogError(ex, "Error processing connection {ConnectionId}", connection.ConnectionId);
                        }
                        finally
                        {
                            ConnectionRemoved?.Invoke(connection);
                            _connections.TryRemove(connection.ConnectionId, out _);
                        }
                    }, _cts.Token);
                }
                catch (OperationCanceledException)
                {
                    // Expected on cancellation
                    break;
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error accepting new connection");
                }
            }
        }
        finally
        {
            await _listener.StopAsync();
        }
    }

    private async Task ProcessConnectionAsync(IConnection connection)
    {
        var buffer = new byte[1024];
        try
        {
            while (!_cts.IsCancellationRequested)
            {
                try
                {
                    var bytesRead = await connection._networkStream.ReadAsync(buffer, 0, buffer.Length);
                    if (bytesRead == 0) break;

                    var data = _connectionFactory.Deserialize(buffer, bytesRead);
                    if (data is { Type: "handshake" } handshakeData)
                    {
                        connection.UserId = handshakeData.Data.ToString();
                        await connection.SendSystemMessageAsync($"Welcome, {connection.UserId}!");
                    }
                    else if (data is { Type: "join" } joinData)
                    {
                        var roomId = joinData.Data.ToString();
                        if (await _connectionFactory.RoomManager.JoinRoomAsync(connection.ConnectionId, roomId))
                        {
                            connection.RoomId = roomId;
                            await connection.SendSystemMessageAsync($"Joined room: {roomId}");
                        }
                        else
                        {
                            await connection.SendSystemMessageAsync($"Failed to join room: {roomId}");
                        }
                    }
                    else if (data is { Type: "message" } messageData)
                    {
                        var message = (ChatMessage)messageData.Data;
                        message.SenderId = connection.UserId;
                        message.RoomId = connection.RoomId ?? throw new InvalidOperationException("No room joined");

                        await _connectionFactory.MessageProcessor.ProcessMessageAsync(message);
                    }
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error processing message from {ConnectionId}", connection.ConnectionId);
                    break;
                }
            }
        }
        finally
        {
            await connection.CloseAsync();
        }
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (!_disposed)
        {
            if (disposing)
            {
                _cts.Cancel();
                _cts.Dispose();
                _listener?.Stop();
                foreach (var connection in _connections.Values)
                {
                    connection.Dispose();
                }
                _connections.Clear();
            }
            _disposed = true;
        }
    }

    ~TcpConnectionManager()
    {
        Dispose(false);
    }
}

// ConnectionManager/ConnectionFactory.cs
public class ConnectionFactory : IConnectionFactory
{
    private readonly ILogger<ConnectionFactory> _logger;
    private readonly IMessageProcessor _messageProcessor;
    private readonly IRoomManager _roomManager;

    public ConnectionFactory(
        ILogger<ConnectionFactory> logger,
        IMessageProcessor messageProcessor,
        IRoomManager roomManager)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _messageProcessor = messageProcessor ?? throw new ArgumentNullException(nameof(messageProcessor));
        _roomManager = roomManager ?? throw new ArgumentNullException(nameof(roomManager));
    }

    public IConnection CreateConnection(TcpClient tcpClient)
    {
        var connectionId = Guid.NewGuid().ToString();
        return new TcpConnection(tcpClient, connectionId, _logger, _messageProcessor, _roomManager);
    }

    public object Deserialize(byte[] buffer, int bytesRead)
    {
        try
        {
            var stream = new MemoryStream(buffer, 0, bytesRead);
            return new BinaryFormatter().Deserialize(stream);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error deserializing message");
            throw;
        }
    }

    public IMessageProcessor MessageProcessor => _messageProcessor;
    public IRoomManager RoomManager => _roomManager;
}

public interface IConnectionFactory
{
    IConnection CreateConnection(TcpClient tcpClient);
    object Deserialize(byte[] buffer, int bytesRead);
    IMessageProcessor MessageProcessor { get; }
    IRoomManager RoomManager { get; }
}
