## 3. Room Management Subsystem

```csharp
// RoomManagement/RoomManager.cs
public class RoomManager : IRoomManager
{
    private readonly ConcurrentDictionary<string, Room> _rooms = new();
    private readonly ILogger<RoomManager> _logger;
    private readonly IConnectionManager _connectionManager;

    public RoomManager(
        ILogger<RoomManager> logger,
        IConnectionManager connectionManager)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _connectionManager = connectionManager ?? throw new ArgumentNullException(nameof(connectionManager));
    }

    public async Task<string> CreateRoomAsync(string creatorId, string roomName, RoomPermissions permissions)
    {
        var roomId = Guid.NewGuid().ToString();
        var room = new Room(roomId, roomName, permissions);

        // Add creator to room
        var connections = _connectionManager.GetConnections()
            .Where(c => c.UserId == creatorId)
            .ToList();

        foreach (var connection in connections)
        {
            connection.RoomId = roomId;
            room.Members.Add(connection.ConnectionId);
        }

        _rooms.TryAdd(roomId, room);
        _logger.LogInformation("Created room {RoomId} with name {RoomName}", roomId, roomName);

        return roomId;
    }

    public async Task<bool> JoinRoomAsync(string connectionId, string roomId)
    {
        if (!_rooms.TryGetValue(roomId, out var room))
        {
            _logger.LogWarning("Room {RoomId} not found", roomId);
            return false;
        }

        if (!room.Permissions.CanJoin)
        {
            _logger.LogWarning("Room {RoomId} does not allow joining", roomId);
            return false;
        }

        if (room.Members.Contains(connectionId))
        {
            _logger.LogWarning("Connection {ConnectionId} already in room {RoomId}", connectionId, roomId);
            return false;
        }

        var connection = _connectionManager.GetConnections().FirstOrDefault(c => c.ConnectionId == connectionId);
        if (connection == null)
        {
            _logger.LogWarning("Connection {ConnectionId} not found", connectionId);
            return false;
        }

        connection.RoomId = roomId;
        room.Members.Add(connectionId);
        _logger.LogInformation("Connection {ConnectionId} joined room {RoomId}", connectionId, roomId);

        return true;
    }

    public async Task<bool> LeaveRoomAsync(string connectionId)
    {
        var roomId = _connectionManager.GetConnections()
            .FirstOrDefault(c => c.ConnectionId == connectionId)?.RoomId;

        if (roomId == null)
        {
            _logger.LogWarning("Connection {ConnectionId} not in any room", connectionId);
            return false;
        }

        if (!_rooms.TryGetValue(roomId, out var room))
        {
            _logger.LogWarning("Room {RoomId} not found", roomId);
            return false;
        }

        room.Members.Remove(connectionId);
        _logger.LogInformation("Connection {ConnectionId} left room {RoomId}", connectionId, roomId);

        return true;
    }

    public async Task<bool> SendMessageToRoomAsync(string roomId, ChatMessage message)
    {
        if (!_rooms.TryGetValue(roomId, out var room))
        {
            _logger.LogWarning("Room {RoomId} not found", roomId);
            return false;
        }

        if (!room.Permissions.CanSendMessages)
        {
            _logger.LogWarning("Room {RoomId} does not allow sending messages", roomId);
            return false;
        }

        var connections = _connectionManager.GetConnections()
            .Where(c => c.RoomId == roomId)
            .ToList();

        foreach (var connection in connections)
        {
            try
            {
                await connection.SendMessageAsync(message);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error sending message to connection {ConnectionId}", connection.ConnectionId);
            }
        }

        return true;
    }

    public async Task<bool> BroadcastSystemMessageAsync(string roomId, string message)
    {
        if (!_rooms.TryGetValue(roomId, out var room))
        {
            _logger.LogWarning("Room {RoomId} not found", roomId);
            return false;
        }

        var connections = _connectionManager.GetConnections()
            .Where(c => c.RoomId == roomId)
            .ToList();

        foreach (var connection in connections)
        {
            try
            {
                await connection.SendSystemMessageAsync(message);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error sending system message to connection {ConnectionId}", connection.ConnectionId);
            }
        }

        return true;
    }

    public async Task<IEnumerable<string>> GetRoomMembersAsync(string roomId)
    {
        if (!_rooms.TryGetValue(roomId, out var room))
        {
            _logger.LogWarning("Room {RoomId} not found", roomId);
            return Array.Empty<string>();
        }

        return room.Members;
    }

    public async Task<RoomPermissions> GetRoomPermissionsAsync(string roomId)
    {
        if (!_rooms.TryGetValue(roomId, out var room))
        {
            _logger.LogWarning("Room {RoomId} not found", roomId);
            return new RoomPermissions();
        }

        return room.Permissions;
    }

    public async Task<bool> UpdateRoomPermissionsAsync(string roomId, RoomPermissions permissions)
    {
        if (!_rooms.TryGetValue(roomId, out var room))
        {
            _logger.LogWarning("Room {RoomId} not found", roomId);
            return false;
        }

        room.Permissions = permissions;
        _logger.LogInformation("Updated permissions for room {RoomId}", roomId);
        return true;
    }
}

public class Room
{
    public string Id { get; }
    public string Name { get; }
    public RoomPermissions Permissions { get; set; }
    public ConcurrentBag<string> Members { get; } = new();

    public Room(string id, string name, RoomPermissions permissions)
    {
        Id = id;
        Name = name;
        Permissions = permissions;
    }
}
