## 4. Message Persistence Engine

```csharp
// PersistenceEngine/MessageRepository.cs
public class MessageRepository : IMessagesRepository
{
    private readonly DbContext _dbContext;
    private readonly ILogger<MessageRepository> _logger;
    private readonly SemaphoreSlim _semaphore = new(1, 1);

    public MessageRepository(
        DbContext dbContext,
        ILogger<MessageRepository> logger)
    {
        _dbContext = dbContext ?? throw new ArgumentNullException(nameof(dbContext));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task AddMessageAsync(ChatMessage message)
    {
        await _semaphore.WaitAsync();

        try
        {
            var dbMessage = new DbMessage
            {
                Id = message.Id,
                SenderId = message.SenderId,
                RoomId = message.RoomId,
                Content = message.Content,
                Timestamp = message.Timestamp,
                ImageUrl = message.ImageUrl,
                Type = message.Type
            };

            _dbContext.Messages.Add(dbMessage);
            await _dbContext.SaveChangesAsync();
            _logger.LogDebug("Added message {MessageId} to database", message.Id);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error adding message {MessageId} to database", message.Id);
            throw;
        }
        finally
        {
            _semaphore.Release();
        }
    }

    public async Task<IEnumerable<ChatMessage>> GetMessagesAsync(string roomId, int limit = 100)
    {
        await _semaphore.WaitAsync();

        try
        {
            var dbMessages = await _dbContext.Messages
                .Where(m => m.RoomId == roomId)
                .OrderByDescending(m => m.Timestamp)
                .Take(limit)
                .ToListAsync();

            return dbMessages.Select(m => new ChatMessage
            {
                Id = m.Id,
                SenderId = m.SenderId,
                RoomId = m.RoomId,
                Content = m.Content,
                Timestamp = m.Timestamp,
                ImageUrl = m.ImageUrl,
                Type = m.Type
            });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error getting messages for room {RoomId}", roomId);
            throw;
        }
        finally
        {
            _semaphore.Release();
        }
    }

    public async Task<IEnumerable<ChatMessage>> GetMessagesSinceAsync(string roomId, DateTime since)
    {
        await _semaphore.WaitAsync();

        try
        {
            var dbMessages = await _dbContext.Messages
                .Where(m => m.RoomId == roomId && m.Timestamp > since)
                .OrderBy(m => m.Timestamp)
                .ToListAsync();

            return dbMessages.Select(m => new ChatMessage
            {
                Id = m.Id,
                SenderId = m.SenderId,
                RoomId = m.RoomId,
                Content = m.Content,
                Timestamp = m.Timestamp,
                ImageUrl = m.ImageUrl,
                Type = m.Type
            });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error getting messages since {Since} for room {RoomId}", since, roomId);
            throw;
        }
        finally
        {
            _semaphore.Release();
        }
    }
}

// PersistenceEngine/DbMessage.cs
public class DbMessage
{
    public Guid Id { get; set; }
    public string SenderId { get; set; }
    public string RoomId { get; set; }
    public string Content { get; set; }
    public DateTime Timestamp { get; set; }
    public string? ImageUrl { get; set; }
    public MessageType Type { get; set; }
}

// PersistenceEngine/DbContext.cs
public class ChatDbContext : DbContext
{
    public DbSet<DbMessage> Messages { get; set; }

    public ChatDbContext(DbContextOptions<ChatDbContext> options) : base(options)
    {
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<DbMessage>()
            .HasIndex(m => new { m.RoomId, m.Timestamp })
            .IsUnique(false);

        modelBuilder.Entity<DbMessage>()
            .Property(m => m.Timestamp)
            .HasDefaultValueSql("GETUTCDATE()");
    }
}
