## 5. Message Processor

```csharp
// MessageProcessor/MessageProcessor.cs
public class MessageProcessor : IMessageProcessor
{
    private readonly ILogger<MessageProcessor> _logger;
    private readonly IMessagesRepository _messagesRepository;
    private readonly IRoomManager _roomManager;
    private readonly IConnectionManager _connectionManager;

    public MessageProcessor(
        ILogger<MessageProcessor> logger,
        IMessagesRepository messagesRepository,
        IRoomManager roomManager,
        IConnectionManager connectionManager)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _messagesRepository = messagesRepository ?? throw new ArgumentNullException(nameof(messagesRepository));
        _roomManager = roomManager ?? throw new ArgumentNullException(nameof(roomManager));
        _connectionManager = connectionManager ?? throw new ArgumentNullException(nameof(connectionManager));
    }

    public async Task ProcessMessageAsync(ChatMessage message)
    {
        try
        {
            // 1. Persist the message
            await _messagesRepository.AddMessageAsync(message);

            // 2. Broadcast to room
            await _roomManager.SendMessageToRoomAsync(message.RoomId, message);

            // 3. Optionally send to other systems (e.g., notifications)
            await SendToExternalSystemsAsync(message);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing message {MessageId}", message.Id);
            throw;
        }
    }

    private async Task SendToExternalSystemsAsync(ChatMessage message)
    {
        // In a real implementation, this would send to notification services, analytics, etc.
        _logger.LogInformation("Message {MessageId} processed - would send to external systems", message.Id);
    }
}
