## 6. Main Application Host

```csharp
// ChatServerHost/Program.cs
public class Program
{
    public static async Task Main(string[] args)
    {
        var builder = Host.CreateApplicationBuilder(args);

        // Configure services
        builder.Services.AddLogging(configure => configure.AddConsole());
        builder.Services.AddDbContext<ChatDbContext>(options =>
            options.UseSqlServer(builder.Configuration.GetConnectionString("DefaultConnection")));

        // Register components
        builder.Services.AddSingleton<IConnectionManager, TcpConnectionManager>();
        builder.Services.AddSingleton<IConnectionFactory, ConnectionFactory>();
        builder.Services.AddSingleton<IRoomManager, RoomManager>();
        builder.Services.AddSingleton<IMessagesRepository, MessageRepository>();
        builder.Services.AddSingleton<IMessageProcessor, MessageProcessor>();

        // Configure TCP connection manager
        builder.Services.Configure<TcpConnectionManagerOptions>(builder.Configuration.GetSection("TcpConnectionManager"));

        var app = builder.Build();

        // Start components
        var connectionManager = app.Services.GetRequiredService<IConnectionManager>();
        var roomManager = app.Services.GetRequiredService<IRoomManager>();
        var messageProcessor = app.Services.GetRequiredService<IMessageProcessor>();

        try
        {
            await connectionManager.StartAsync();
            await app.RunAsync();
        }
        catch (Exception ex)
        {
            app.Logger.LogError(ex, "Application terminated unexpectedly");
            throw;
        }
    }
}

// ChatServerHost/ConnectionManagerOptions.cs
public class TcpConnectionManagerOptions
